#include <cstdio>
#include <cstdlib>
#include <cmath>
#include <string>
#include <vector>
#include <fstream>
#include <sstream>
#include "cJSON.h"
#include "lodepng.h"

struct Layer {
    int out = 0;
    int in = 0;
    std::vector<float> w;
    std::vector<float> b;
};

static std::string readFile(const char* path) {
    std::ifstream f(path, std::ios::binary);
    if (!f) return std::string();
    std::ostringstream ss;
    ss << f.rdbuf();
    return ss.str();
}

static bool loadLayer(const cJSON* root, const char* name, Layer& layer) {
    cJSON* obj = cJSON_GetObjectItemCaseSensitive(root, name);
    if (!obj) return false;
    cJSON* shape = cJSON_GetObjectItemCaseSensitive(obj, "shape");
    cJSON* data = cJSON_GetObjectItemCaseSensitive(obj, "data");
    if (!shape || !data) return false;

    if (cJSON_GetArraySize(shape) == 2) {
        layer.out = (int)cJSON_GetArrayItem(shape, 0)->valuedouble;
        layer.in = (int)cJSON_GetArrayItem(shape, 1)->valuedouble;
    } else if (cJSON_GetArraySize(shape) == 1) {
        layer.out = (int)cJSON_GetArrayItem(shape, 0)->valuedouble;
        layer.in = 1;
    } else {
        return false;
    }

    int n = cJSON_GetArraySize(data);
    layer.w.resize((size_t)layer.out * layer.in);
    for (int i = 0; i < layer.out * layer.in && i < n; ++i)
        layer.w[i] = (float)cJSON_GetArrayItem(data, i)->valuedouble;
    return n >= layer.out * layer.in;
}

static bool loadBias(const cJSON* root, const char* name, Layer& layer) {
    cJSON* obj = cJSON_GetObjectItemCaseSensitive(root, name);
    if (!obj) return false;
    cJSON* data = cJSON_GetObjectItemCaseSensitive(obj, "data");
    if (!data) return false;
    int n = cJSON_GetArraySize(data);
    if (n < layer.out) return false;
    layer.b.resize(layer.out);
    for (int i = 0; i < layer.out; ++i)
        layer.b[i] = (float)cJSON_GetArrayItem(data, i)->valuedouble;
    return true;
}

static void linear(const Layer& layer, const std::vector<float>& x,
                   std::vector<float>& y, bool relu) {
    y.resize(layer.out);
    for (int o = 0; o < layer.out; ++o) {
        float sum = layer.b[o];
        const float* row = &layer.w[(size_t)o * layer.in];
        for (int i = 0; i < layer.in; ++i) sum += row[i] * x[i];
        y[o] = relu && sum < 0.0f ? 0.0f : sum;
    }
}

static unsigned char toGray(unsigned char r, unsigned char g,
                            unsigned char b, unsigned char a) {
    float v = 0.299f * r + 0.587f * g + 0.114f * b;
    v *= a / 255.0f;  // composite over black
    int iv = (int)(v + 0.5f);
    if (iv < 0) iv = 0;
    if (iv > 255) iv = 255;
    return (unsigned char)iv;
}

static std::vector<float> loadImage(const char* path) {
    std::vector<unsigned char> image;
    unsigned w = 0, h = 0;
    unsigned err = lodepng::decode(image, w, h, path);
    if (err) {
        std::fprintf(stderr, "PNG decode error: %s\n", lodepng_error_text(err));
        std::exit(1);
    }

    std::vector<float> gray((size_t)w * h);
    for (unsigned i = 0; i < w * h; ++i)
        gray[i] = toGray(image[4 * i], image[4 * i + 1],
                         image[4 * i + 2], image[4 * i + 3]);

    const int S = 28;
    std::vector<float> out((size_t)S * S);
    if (w == S && h == S) {
        out = gray;
    } else {
        // Bilinear resize to the model's 28x28 input.
        for (int y = 0; y < S; ++y) {
            float sy = (h > 1) ? (float)y * (h - 1) / (S - 1) : 0.0f;
            int y0 = (int)sy;
            int y1 = y0 + 1 < (int)h ? y0 + 1 : y0;
            float fy = sy - y0;
            for (int x = 0; x < S; ++x) {
                float sx = (w > 1) ? (float)x * (w - 1) / (S - 1) : 0.0f;
                int x0 = (int)sx;
                int x1 = x0 + 1 < (int)w ? x0 + 1 : x0;
                float fx = sx - x0;
                float top = gray[(size_t)y0 * w + x0] * (1 - fx) +
                            gray[(size_t)y0 * w + x1] * fx;
                float bot = gray[(size_t)y1 * w + x0] * (1 - fx) +
                            gray[(size_t)y1 * w + x1] * fx;
                out[(size_t)y * S + x] = top * (1 - fy) + bot * fy;
            }
        }
    }

    // MNIST normalization used during training.
    for (float& v : out) v = (v / 255.0f - 0.1307f) / 0.3081f;
    return out;
}

int main(int argc, char** argv) {
    if (argc != 3) {
        std::fprintf(stderr, "Usage: %s weights.json image.png\n", argv[0]);
        return 1;
    }

    std::string json = readFile(argv[1]);
    if (json.empty()) {
        std::fprintf(stderr, "Could not read weights file: %s\n", argv[1]);
        return 1;
    }
    cJSON* root = cJSON_Parse(json.c_str());
    if (!root) {
        std::fprintf(stderr, "Could not parse weights JSON\n");
        return 1;
    }

    Layer l1, l2, l3;
    bool ok = loadLayer(root, "input_layer.weight", l1) &&
              loadBias(root, "input_layer.bias", l1) &&
              loadLayer(root, "hidden_layer.weight", l2) &&
              loadBias(root, "hidden_layer.bias", l2) &&
              loadLayer(root, "output_layer.weight", l3) &&
              loadBias(root, "output_layer.bias", l3);
    cJSON_Delete(root);
    if (!ok) {
        std::fprintf(stderr, "Invalid weights JSON\n");
        return 1;
    }

    std::vector<float> x = loadImage(argv[2]);
    std::vector<float> a, b, o;
    linear(l1, x, a, true);
    linear(l2, a, b, true);
    linear(l3, b, o, false);

    int best = 0;
    for (int i = 1; i < (int)o.size(); ++i)
        if (o[i] > o[best]) best = i;

    std::printf("%d\n", best);

    std::ofstream pf("prediction.txt");
    if (pf) pf << best << "\n";

    return 0;
}

